/* next.config.ts —— 开启 Partial Prerendering */
import type { NextConfig } from 'next';

const nextConfig: NextConfig = {
  experimental: {
    ppr: 'incremental', // 允许按 route segment 逐个启用 PPR
  },
};

export default nextConfig;

/* ------------------------------------------------------------ */
/* app/products/[id]/page.tsx                                   */
/* ------------------------------------------------------------ */
import { Suspense } from 'react';

// 1) 该 route segment 参与 Partial Prerendering
export const experimental_ppr = true;

// 2) 构建期预生成静态外壳的路径
export function generateStaticParams() {
  return [{ id: 'keyboard-01' }, { id: 'mouse-02' }];
}

// 3) 静态数据：构建期渲染，60s 后台重新验证（ISR）
async function getProduct(id: string) {
  const res = await fetch(`https://api.example.com/products/${id}`, {
    next: { revalidate: 60 },
  });
  return res.json();
}

// 4) 动态数据：强制动态，必须在请求时渲染
async function getLivePrice(id: string) {
  const res = await fetch(`https://api.example.com/price/${id}`, {
    cache: 'no-store',
  });
  return res.json();
}

async function getReviews(id: string) {
  const res = await fetch(`https://api.example.com/reviews/${id}`, {
    cache: 'no-store',
  });
  return res.json();
}

// 5) 动态子组件：内部 await 一个 no-store 的请求，形成「动态洞」
async function PricePanel({ id }: { id: string }) {
  const price = await getLivePrice(id);
  return (
    <section className="rounded-xl border p-4" style={{ height: 80 }}>
      实时价格：￥{price.amount}
    </section>
  );
}

async function Reviews({ id }: { id: string }) {
  const reviews = await getReviews(id);
  return (
    <ul className="space-y-2" style={{ minHeight: 200 }}>
      {reviews.map((r: { id: string; text: string }) => (
        <li key={r.id}>{r.text}</li>
      ))}
    </ul>
  );
}

// fallback 必须与真实内容等高，避免布局抖动（CLS）
function PriceSkeleton() {
  return <div className="animate-pulse bg-gray-200 rounded-xl" style={{ height: 80 }} />;
}
function ReviewsSkeleton() {
  return <div className="animate-pulse bg-gray-200 rounded-xl" style={{ minHeight: 200 }} />;
}

export default async function ProductPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { id } = await params;          // Next 15：params 是 Promise
  const product = await getProduct(id); // 静态：进入预渲染外壳

  return (
    <main className="mx-auto max-w-3xl p-6 space-y-6">
      {/* 静态外壳：随首字节立刻下发 */}
      <h1 className="text-3xl font-bold">{product.name}</h1>
      <p className="text-gray-600">{product.description}</p>

      {/* 两个独立的流式边界：互不阻塞，各自按速度落地 */}
      <Suspense fallback={<PriceSkeleton />}>
        <PricePanel id={id} />
      </Suspense>

      <Suspense fallback={<ReviewsSkeleton />}>
        <Reviews id={id} />
      </Suspense>
    </main>
  );
}

